use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let jobs = input.as_array().unwrap();
    let quantum = input.as_u64().unwrap();
    let mut result = Vec::new();
    let mut work = 0;
    let mut indices = Vec::new();

    for (i, job) in jobs.iter().enumerate() {
        let job_value = job.as_i64().unwrap();
        if job_value < 0 {
            return Value::Null;
        }
        work += job_value;
        if work > quantum {
            result.push(indices.pop().unwrap() as u64);
            work -= quantum;
        }
    }

    Value::Array(result.into_iter().map(|x| Value::U64(x)).collect())
}
